// Pointer-driven drag and drop. No HTML5 DnD: we own the ghost, the hit testing,
// the indicator and auto-scroll, so it feels the same in every browser.

import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react"
import type { PointerEvent as ReactPointerEvent, ReactNode } from "react"
import { ACCENT } from "./chrome"

export type DragPayload = { kind: "new"; type: string } | { kind: "move"; id: string; type: string } | { kind: "block"; id: string; type: "block"; name: string }

type Rect = { x: number; y: number; w: number; h: number }
export type DropTarget = { parentId: string; index: number; line: Rect; empty: boolean; box: Rect; label: string }

type DragState = { payload: DragPayload; x: number; y: number; target: DropTarget | null }

type Ctx = {
  drag: DragState | null
  /** The node that just landed, for a short flash. */
  landed: string | null
  begin: (e: ReactPointerEvent, payload: DragPayload) => void
}

const DragCtx = createContext<Ctx>({ drag: null, landed: null, begin: () => {} })
export const useDrag = () => useContext(DragCtx)

const THRESHOLD = 4
const EDGE = 64
const toRect = (r: DOMRect): Rect => ({ x: r.left, y: r.top, w: r.width, h: r.height })

// Where in `slot` the pointer would drop, and the line to draw for it.
function measure(slot: HTMLElement, x: number, y: number) {
  const flow = slot.dataset.skcFlow as "column" | "row" | "grid"
  const kids = Array.from(slot.children).filter((el): el is HTMLElement => (el as HTMLElement).dataset.skcNode !== undefined)
  const box = slot.getBoundingClientRect()
  if (kids.length === 0) return { index: 0, empty: true, line: { x: box.left + 2, y: box.top + 2, w: box.width - 4, h: Math.max(box.height - 4, 24) }, kids }
  let index = kids.length
  for (let i = 0; i < kids.length; i++) {
    const r = kids[i].getBoundingClientRect()
    const before = flow === "column" ? y < r.top + r.height / 2 : y < r.top || (y <= r.bottom && x < r.left + r.width / 2)
    if (before) {
      index = i
      break
    }
  }
  const last = kids[kids.length - 1].getBoundingClientRect()
  if (flow === "column") {
    const next = kids[index]?.getBoundingClientRect()
    const prev = index > 0 ? kids[index - 1].getBoundingClientRect() : null
    const lineY = !next ? last.bottom + 4 : prev ? (prev.bottom + next.top) / 2 : next.top - 4
    return { index, empty: false, line: { x: box.left, y: lineY - 1.5, w: box.width, h: 3 }, kids }
  }
  const ref = (kids[index] ?? kids[kids.length - 1]).getBoundingClientRect()
  const prev = index > 0 && kids[index] ? kids[index - 1].getBoundingClientRect() : null
  const sameLine = prev && Math.abs(prev.top - ref.top) < 4
  const lineX = !kids[index] ? last.right + 4 : sameLine && prev ? (prev.right + ref.left) / 2 : ref.left - 4
  return { index, empty: false, line: { x: lineX - 1.5, y: ref.top, w: 3, h: ref.height }, kids }
}

/** Find the innermost container under the pointer that can take the payload. */
function hitTest(x: number, y: number, payload: DragPayload, labelOf: (id: string) => string): DropTarget | null {
  const dragged = payload.kind === "move" ? document.querySelector<HTMLElement>(`[data-skc-node="${payload.id}"]`) : null
  for (const el of document.elementsFromPoint(x, y)) {
    let slot = el.closest<HTMLElement>("[data-skc-slot]")
    while (slot && dragged?.contains(slot)) slot = slot.parentElement?.closest<HTMLElement>("[data-skc-slot]") ?? null
    if (!slot) continue
    const m = measure(slot, x, y)
    // Dropping a node right where it already is does nothing: show nothing.
    if (dragged && dragged.parentElement === slot) {
      const from = m.kids.indexOf(dragged)
      if (m.index === from || m.index === from + 1) return null
    }
    const owner = slot.closest<HTMLElement>("[data-skc-node]")
    const parentId = slot.dataset.skcSlot!
    return {
      parentId,
      index: m.index,
      line: m.line,
      empty: m.empty,
      box: toRect((owner ?? slot).getBoundingClientRect()),
      label: labelOf(parentId),
    }
  }
  return null
}

export function DragProvider({
  children,
  onDrop,
  labelOf,
  scroller,
  edgePan,
}: {
  children: ReactNode
  onDrop: (payload: DragPayload, target: DropTarget) => string | void
  labelOf: (id: string) => string
  scroller: React.RefObject<HTMLElement | null>
  /** Pans the view by (dx, dy) screen pixels when the pointer rests near an edge. */
  edgePan: (dx: number, dy: number) => void
}) {
  const [drag, setDrag] = useState<DragState | null>(null)
  const [landed, setLanded] = useState<string | null>(null)
  const live = useRef<{ payload: DragPayload; sx: number; sy: number; x: number; y: number; active: boolean } | null>(null)
  const frame = useRef(0)
  const scrollLoop = useRef(0)
  const cbs = useRef({ onDrop, labelOf, edgePan })
  cbs.current = { onDrop, labelOf, edgePan }

  const update = useCallback(() => {
    frame.current = 0
    const l = live.current
    if (!l?.active) return
    setDrag({ payload: l.payload, x: l.x, y: l.y, target: hitTest(l.x, l.y, l.payload, cbs.current.labelOf) })
  }, [])

  // Scroll the canvas while the pointer rests near its top or bottom edge.
  const autoScroll = useCallback(() => {
    const l = live.current
    const el = scroller.current
    if (!l?.active || !el) {
      scrollLoop.current = 0
      return
    }
    const r = el.getBoundingClientRect()
    const inside = l.x > r.left && l.x < r.right && l.y > r.top && l.y < r.bottom
    const dy = l.y < r.top + EDGE ? -(r.top + EDGE - l.y) : l.y > r.bottom - EDGE ? l.y - (r.bottom - EDGE) : 0
    const dx = l.x < r.left + EDGE ? -(r.left + EDGE - l.x) : l.x > r.right - EDGE ? l.x - (r.right - EDGE) : 0
    if (inside && (dx || dy)) {
      const speed = (v: number) => -Math.sign(v) * Math.min(18, Math.abs(v) * 0.3)
      cbs.current.edgePan(dx ? speed(dx) : 0, dy ? speed(dy) : 0)
      if (!frame.current) frame.current = requestAnimationFrame(update)
    }
    scrollLoop.current = requestAnimationFrame(autoScroll)
  }, [scroller, update])

  const end = useCallback(
    (commit: boolean) => {
      const l = live.current
      live.current = null
      cancelAnimationFrame(frame.current)
      cancelAnimationFrame(scrollLoop.current)
      frame.current = 0
      document.documentElement.removeAttribute("data-skc-dragging")
      if (l?.active) {
        // The pointerup that ends a drag must not also click what is under it.
        const swallow = (e: MouseEvent) => {
          e.stopPropagation()
          e.preventDefault()
        }
        window.addEventListener("click", swallow, { capture: true, once: true })
        window.setTimeout(() => window.removeEventListener("click", swallow, { capture: true }), 0)
        const target = commit ? hitTest(l.x, l.y, l.payload, cbs.current.labelOf) : null
        if (target) {
          const id = cbs.current.onDrop(l.payload, target)
          if (id) {
            setLanded(id)
            window.setTimeout(() => setLanded((x) => (x === id ? null : x)), 700)
          }
        }
      }
      setDrag(null)
    },
    [],
  )

  useEffect(() => {
    const move = (e: PointerEvent) => {
      const l = live.current
      if (!l) return
      l.x = e.clientX
      l.y = e.clientY
      if (!l.active) {
        if (Math.hypot(l.x - l.sx, l.y - l.sy) < THRESHOLD) return
        l.active = true
        document.getSelection()?.removeAllRanges()
        document.documentElement.setAttribute("data-skc-dragging", "")
        scrollLoop.current = requestAnimationFrame(autoScroll)
      }
      e.preventDefault()
      if (!frame.current) frame.current = requestAnimationFrame(update)
    }
    const up = () => live.current && end(true)
    const cancel = () => live.current && end(false)
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape" && live.current?.active) {
        e.preventDefault()
        e.stopImmediatePropagation()
        end(false)
      }
    }
    window.addEventListener("pointermove", move, { passive: false })
    window.addEventListener("pointerup", up)
    window.addEventListener("pointercancel", cancel)
    window.addEventListener("keydown", key, true)
    window.addEventListener("blur", cancel)
    return () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", up)
      window.removeEventListener("pointercancel", cancel)
      window.removeEventListener("keydown", key, true)
      window.removeEventListener("blur", cancel)
    }
  }, [autoScroll, end, update])

  const begin = useCallback((e: ReactPointerEvent, payload: DragPayload) => {
    if (e.button !== 0 || e.altKey || e.ctrlKey || e.metaKey) return
    // Don't steal pointer-downs meant for fields in the inspector or inline editors.
    if ((e.target as HTMLElement).closest("input, textarea, select")) return
    e.stopPropagation()
    live.current = { payload, sx: e.clientX, sy: e.clientY, x: e.clientX, y: e.clientY, active: false }
  }, [])

  return <DragCtx.Provider value={{ drag, landed, begin }}>{children}</DragCtx.Provider>
}

/** The ghost under the cursor, the target outline and the insertion line. */
export function DragOverlay({ renderGhost }: { renderGhost: (payload: DragPayload) => ReactNode }) {
  const { drag } = useDrag()
  if (!drag) return null
  const t = drag.target
  const ease = "cubic-bezier(.32,.72,0,1)"
  return (
    <div className="pointer-events-none fixed inset-0 z-[2147483646]">
      {t && (
        <div
          className="absolute top-0 left-0 rounded-[8px]"
          style={{
            transform: `translate3d(${t.box.x - 3}px, ${t.box.y - 3}px, 0)`,
            width: t.box.w + 6,
            height: t.box.h + 6,
            boxShadow: `0 0 0 1px ${ACCENT}55`,
            background: `${ACCENT}08`,
            transition: `transform .14s ${ease}, width .14s ${ease}, height .14s ${ease}`,
          }}
        />
      )}
      {t && (
        <div
          className="absolute top-0 left-0"
          style={{
            transform: `translate3d(${t.line.x}px, ${t.line.y}px, 0)`,
            width: t.line.w,
            height: t.line.h,
            borderRadius: t.empty ? 8 : 999,
            background: t.empty ? `${ACCENT}12` : ACCENT,
            outline: t.empty ? `1.5px dashed ${ACCENT}` : undefined,
            outlineOffset: -1.5,
            boxShadow: t.empty ? undefined : `0 0 0 3px ${ACCENT}26`,
            transition: `transform .12s ${ease}, width .12s ${ease}, height .12s ${ease}`,
          }}
        >
          {t.empty && (
            <span className="absolute inset-0 flex items-center justify-center font-sans text-[11px] font-medium" style={{ color: ACCENT }}>
              Drop into {t.label}
            </span>
          )}
        </div>
      )}
      <div className="absolute top-0 left-0" style={{ transform: `translate3d(${drag.x + 12}px, ${drag.y + 10}px, 0)` }}>
        <div className="skc-ghost">
          {renderGhost(drag.payload)}
          <span className="skc-ghost-where" data-off={t ? undefined : ""}>
            {t ? `in ${t.label}` : "Not here"}
          </span>
        </div>
      </div>
    </div>
  )
}

import type { Theme } from "./theme"

// Sketch Format v1: the data a sketch is made of, and pure helpers for editing it.

export type PropValue = string | number | boolean
export type Props = Record<string, PropValue>

export type SketchNode = {
  id: string
  type: string
  props: Props
  children?: SketchNode[]
  /** Free-text intent for the agent: "filters the table below". */
  note?: string
  /** Where it sits in its parent: left/center/right in a column or grid, top/middle/bottom in a row. */
  align?: Align
  /** Screen id this element navigates to when clicked. */
  link?: string
}

export type Align = "start" | "center" | "end"
export type Flow = "column" | "row" | "grid"

/** Classes for a node's wrapper given its alignment and the parent's flow. */
export function alignClass(align: Align | undefined, flow: Flow | undefined) {
  if (!align || !flow) return ""
  if (flow === "row") return { start: "self-start", center: "self-center", end: "self-end" }[align]
  if (flow === "grid") return { start: "justify-self-start", center: "justify-self-center text-center", end: "justify-self-end text-right" }[align]
  return { start: "self-start", center: "self-center text-center", end: "self-end text-right" }[align]
}

/** Wrapper classes for nodes that fill their parent: the body column, sidebar surfaces, spacers. */
export function fillClass(node: SketchNode) {
  if (node.type === "spacer") return "flex-1"
  if (node.props.region === "body" || node.props.surface === "sidebar") return "flex flex-1 flex-col"
  return ""
}

/** "full": edge to edge, no padding, for app layouts made of panes. */
export type Shell = "none" | "sidebar" | "topbar" | "full"
export type Device = "desktop" | "mobile"

export type Screen = {
  id: string
  name: string
  path: string
  device: Device
  shell: Shell
  purpose?: string
  root: SketchNode
}

export type NavItem = { id: string; label: string; link?: string }

export type SketchDoc = {
  version: 1
  app: { name: string; nav: NavItem[] }
  screens: Screen[]
  /** Overrides on top of the project's theme; empty means the project's own. */
  theme?: Theme
}

export const uid = () => Math.random().toString(36).slice(2, 9)

export function findNode(root: SketchNode, id: string): SketchNode | null {
  if (root.id === id) return root
  for (const child of root.children ?? []) {
    const hit = findNode(child, id)
    if (hit) return hit
  }
  return null
}

export function findParent(
  root: SketchNode,
  id: string,
): { parent: SketchNode; index: number } | null {
  const children = root.children ?? []
  const index = children.findIndex((c) => c.id === id)
  if (index !== -1) return { parent: root, index }
  for (const child of children) {
    const hit = findParent(child, id)
    if (hit) return hit
  }
  return null
}

/** Returns a copy of the tree with `fn` applied to the node with `id`. */
export function mapNode(
  root: SketchNode,
  id: string,
  fn: (node: SketchNode) => SketchNode,
): SketchNode {
  if (root.id === id) return fn(root)
  if (!root.children) return root
  return { ...root, children: root.children.map((c) => mapNode(c, id, fn)) }
}

export function removeNode(root: SketchNode, id: string): SketchNode {
  if (!root.children) return root
  return {
    ...root,
    children: root.children
      .filter((c) => c.id !== id)
      .map((c) => removeNode(c, id)),
  }
}

export function insertNode(
  root: SketchNode,
  parentId: string,
  index: number,
  node: SketchNode,
): SketchNode {
  return mapNode(root, parentId, (parent) => {
    const children = [...(parent.children ?? [])]
    children.splice(Math.max(0, Math.min(index, children.length)), 0, node)
    return { ...parent, children }
  })
}

export function isAncestor(root: SketchNode, ancestorId: string, id: string) {
  const ancestor = findNode(root, ancestorId)
  return !!ancestor && ancestorId !== id && !!findNode(ancestor, id)
}

export function moveNode(
  root: SketchNode,
  id: string,
  parentId: string,
  index: number,
): SketchNode {
  if (id === parentId || isAncestor(root, id, parentId)) return root
  const node = findNode(root, id)
  const from = findParent(root, id)
  if (!node || !from) return root
  // Moving later inside the same parent: account for the removed slot.
  const adjusted =
    from.parent.id === parentId && from.index < index ? index - 1 : index
  return insertNode(removeNode(root, id), parentId, adjusted, node)
}

/** Deep copy with fresh ids. */
export function cloneNode(node: SketchNode): SketchNode {
  return {
    ...node,
    id: uid(),
    props: { ...node.props },
    children: node.children?.map(cloneNode),
  }
}

export function walk(root: SketchNode, fn: (node: SketchNode) => void) {
  fn(root)
  root.children?.forEach((c) => walk(c, fn))
}

import { LayoutTemplate } from "lucide-react"
import { useEffect, useMemo, useState } from "react"
import { ACCENT, Kbd } from "./chrome"
import { Modal } from "./commands"
import type { SketchDoc } from "./format"
import { ScreenThumb } from "./preview"
import type { Theme } from "./theme"
import type { Template } from "./templates"
import { TEMPLATES } from "./templates"

export type Built = ReturnType<Template["build"]>

const GROUPS = ["Starter", "App", "AI"] as const

/** Pick a template: see every screen it brings, then add them or start over from it. */
export function TemplateGallery({
  onClose,
  onInsert,
  initial,
  theme,
}: {
  onClose: () => void
  onInsert: (built: Built, mode: "add" | "replace") => void
  initial?: string
  theme?: Theme
}) {
  const [index, setIndex] = useState(() => Math.max(0, TEMPLATES.findIndex((t) => t.id === initial)))
  const template = TEMPLATES[index]
  // Built once per pick, so the thumbnails and the inserted screens are the same.
  const built = useMemo(() => template.build(), [template])
  const app: SketchDoc["app"] = { name: built.app ?? "App", nav: built.nav }

  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault()
        e.stopImmediatePropagation()
        setIndex((i) => (i + (e.key === "ArrowDown" ? 1 : -1) + TEMPLATES.length) % TEMPLATES.length)
      } else if (e.key === "Enter") {
        e.preventDefault()
        e.stopImmediatePropagation()
        onInsert(built, e.shiftKey ? "replace" : "add")
      } else if (e.key === "Escape") {
        e.preventDefault()
        e.stopImmediatePropagation()
        onClose()
      }
    }
    window.addEventListener("keydown", k, true)
    return () => window.removeEventListener("keydown", k, true)
  }, [built, onClose, onInsert])

  const count = built.screens.length

  return (
    <Modal onClose={onClose} className="flex h-[min(620px,calc(100vh-120px))] w-[min(980px,calc(100vw-32px))] flex-col" top="9vh">
      <div className="flex h-12 shrink-0 items-center gap-2 border-b border-(--skc-border) px-4">
        <LayoutTemplate className="size-4 text-(--skc-muted)" />
        <span className="font-medium">Templates</span>
        <span className="ml-auto flex items-center gap-1.5 text-[11px] text-(--skc-muted)">
          <Kbd>↑↓</Kbd> choose <Kbd>↵</Kbd> add <Kbd>⇧↵</Kbd> start from <Kbd>esc</Kbd>
        </span>
      </div>
      <div className="flex min-h-0 flex-1">
        <div role="listbox" aria-label="Templates" className="skc-scroll w-60 shrink-0 overflow-y-auto border-r border-(--skc-border) p-2">
          {GROUPS.map((group) => {
            const items = TEMPLATES.map((t, i) => [t, i] as const).filter(([t]) => (t.category ?? "Starter") === group)
            if (!items.length) return null
            return (
              <div key={group} className="pb-2">
                <div className="px-3 pt-2 pb-1 text-[11px] font-medium text-(--skc-muted)">{group}</div>
                {items.map(([t, i]) => (
                  <button
                    key={t.id}
                    type="button"
                    role="option"
                    aria-selected={i === index}
                    onClick={() => setIndex(i)}
                    className={`flex h-8 w-full items-center rounded-md px-3 text-left text-[12px] ${i === index ? "bg-(--skc-active) font-medium" : "hover:bg-(--skc-hover)"}`}
                  >
                    {t.name}
                  </button>
                ))}
              </div>
            )
          })}
        </div>
        <div className="skc-scroll min-w-0 flex-1 overflow-y-auto bg-(--skc-canvas) p-5">
          <div className="grid grid-cols-2 gap-5">
            {built.screens.map((s) => (
              <figure key={s.id} className="grid gap-2">
                <ScreenThumb screen={s} app={app} theme={theme} width={330} />
                <figcaption className="flex items-baseline gap-2 text-[12px]">
                  <span className="font-medium">{s.name}</span>
                  <span className="truncate font-mono text-[11px] text-(--skc-muted)">{s.path}</span>
                </figcaption>
              </figure>
            ))}
          </div>
        </div>
      </div>
      <div className="flex h-14 shrink-0 items-center gap-2 border-t border-(--skc-border) px-4">
        <span className="min-w-0 truncate text-[12px] text-(--skc-muted)" title={template.credit}>
          {count} screens, linked. {template.credit ?? "Every part stays editable."}
        </span>
        <button
          type="button"
          onClick={() => onInsert(built, "replace")}
          className="ml-auto h-8 rounded-md px-3 text-[13px] text-(--skc-muted) hover:bg-(--skc-hover) hover:text-(--skc-fg)"
          title="Replace the current sketch  ⇧↵"
        >
          Start from this
        </button>
        <button
          type="button"
          onClick={() => onInsert(built, "add")}
          className="h-8 rounded-md px-3 text-[13px] font-medium text-white shadow-[0_1px_2px_rgba(0,0,0,.12)] hover:brightness-110"
          style={{ background: ACCENT }}
          title="Add to the current sketch  ↵"
        >
          Add {count} screens
        </button>
      </div>
    </Modal>
  )
}

import {
  AlignCenterHorizontal,
  AlignCenterVertical,
  AlignEndHorizontal,
  AlignEndVertical,
  AlignStartHorizontal,
  AlignStartVertical,
  ArrowDown,
  ArrowUp,
  ChevronRight,
  CopyPlus,
  Plus,
  Trash,
  X,
} from "lucide-react"
import { useId } from "react"
import type { ReactNode } from "react"
import { Field, IconButton, Segmented, Select, TextArea, TextInput, Toggle, useConfirm } from "./chrome"
import { SHELL_ID } from "./canvas"
import { ACCENT } from "./chrome"
import type { Align, Device, NavItem, Shell, SketchNode } from "./format"
import { findNode, findParent, mapNode, uid } from "./format"
import type { Field as PartField } from "./kit"
import { KIT } from "./kit"
import type { SketchStore } from "./store"

function Section({ title, action, children }: { title: string; action?: ReactNode; children: ReactNode }) {
  return (
    <section className="grid gap-2.5 px-3 pt-2.5 pb-3">
      <div className="flex h-5 items-center justify-between">
        <h3 className="text-[11px] font-semibold text-(--skc-muted)">{title}</h3>
        {action}
      </div>
      {children}
    </section>
  )
}

function PropInput({ id, field, value, onChange }: { id: string; field: PartField; value: unknown; onChange: (v: string | number | boolean) => void }) {
  switch (field.kind) {
    case "textarea":
      return <TextArea id={id} value={String(value ?? "")} onChange={onChange} />
    case "number":
      return <TextInput id={id} type="number" value={Number(value ?? 0)} onChange={(v) => onChange(Number(v))} />
    case "boolean":
      return (
        <div className="flex h-7 items-center">
          <Toggle id={id} on={!!value} onChange={onChange} />
        </div>
      )
    case "select":
      return <Select id={id} value={String(value ?? "")} onChange={onChange} options={(field.options ?? []).map((o) => ({ value: o, label: o }))} />
    default:
      return <TextInput id={id} value={String(value ?? "")} onChange={onChange} />
  }
}

export function Inspector({ store, onDelete }: { store: SketchStore; onDelete: (id: string) => void }) {
  if (store.selectedId === SHELL_ID && (store.screen.shell === "sidebar" || store.screen.shell === "topbar")) return <ShellInspector store={store} />
  const node = store.selectedId ? findNode(store.screen.root, store.selectedId) : null
  return node ? <NodeInspector store={store} node={node} onDelete={onDelete} /> : <ScreenInspector store={store} />
}

/** A short label for the left column; the full one stays in the tooltip. */
const shortLabel = (label: string) => label.replace(/\s*[(:;].*$/, "")

/** One property row: label on the left, control on the right. Long text fields stack. */
function Row({ label, title, stack, children }: { label: string; title?: string; stack?: boolean; children: (id: string) => ReactNode }) {
  const id = useId()
  const text = (
    <label htmlFor={id} title={title ?? label} className="truncate text-[11px] text-(--skc-muted)">
      {label}
    </label>
  )
  if (stack)
    return (
      <div className="grid min-w-0 gap-1">
        {text}
        {children(id)}
      </div>
    )
  return (
    <div className="grid min-h-7 grid-cols-[68px_minmax(0,1fr)] items-center gap-2">
      {text}
      {children(id)}
    </div>
  )
}

function NodeInspector({ store, node, onDelete }: { store: SketchStore; node: SketchNode; onDelete: (id: string) => void }) {
  const part = KIT[node.type]
  const root = store.screen.root
  const loc = findParent(root, node.id)
  const key = `node:${node.id}`
  const update = (fn: (n: SketchNode) => SketchNode, merge?: string) => store.setRoot((r) => mapNode(r, node.id, fn), merge)
  const parent = loc && loc.parent.id !== root.id ? loc.parent : null
  const flow = loc ? (KIT[loc.parent.type]?.container?.flow ?? "column") : "column"

  return (
    <div>
      <div className="flex h-10 items-center gap-0.5 border-b border-(--skc-border) pr-1.5 pl-3">
        <div className="flex min-w-0 flex-1 items-baseline gap-1.5">
          <span className="truncate text-[12px] font-medium">{part?.label ?? node.type}</span>
          {parent && (
            <button type="button" onClick={() => store.select(parent.id)} className="shrink-0 truncate text-[11px] text-(--skc-muted) hover:text-(--skc-fg)" title="Select parent  Esc">
              in {KIT[parent.type]?.label}
            </button>
          )}
        </div>
        <IconButton label="Duplicate" keys="⌘D" onClick={() => store.duplicate(node.id)} disabled={!loc}>
          <CopyPlus />
        </IconButton>
        <IconButton label="Delete" keys="⌫" onClick={() => onDelete(node.id)} disabled={!loc}>
          <Trash />
        </IconButton>
      </div>

      <div className="grid gap-1.5 px-3 py-3">
        {loc && (
          <Row label="Align">
            {() => <AlignControl flow={flow} value={node.align} onChange={(align) => update((n) => ({ ...n, align }))} />}
          </Row>
        )}
        {part?.fields.map((f) => (
          <Row key={f.key} label={shortLabel(f.label)} title={f.label} stack={f.kind === "textarea"}>
            {(id) => <PropInput id={id} field={f} value={node.props[f.key]} onChange={(v) => update((n) => ({ ...n, props: { ...n.props, [f.key]: v } }), `${key}:${f.key}`)} />}
          </Row>
        ))}
      </div>

      <div className="grid gap-1.5 border-t border-(--skc-border) px-3 py-3">
        <Row label="Link">
          {(id) => (
            <Select
              id={id}
              value={node.link ?? ""}
              onChange={(v) => update((n) => ({ ...n, link: v || undefined }))}
              options={[{ value: "", label: "None" }, ...store.doc.screens.map((s) => ({ value: s.id, label: s.name }))]}
            />
          )}
        </Row>
        <TextArea placeholder="Note for the agent" value={node.note ?? ""} onChange={(v) => update((n) => ({ ...n, note: v || undefined }), `${key}:note`)} />
      </div>
    </div>
  )
}

/** Left / center / right in a column or grid, top / middle / bottom in a row. Click the active one to reset. */
function AlignControl({ flow, value, onChange }: { flow: "column" | "row" | "grid"; value?: Align; onChange: (v: Align | undefined) => void }) {
  const row = flow === "row"
  const options: { value: Align; label: string; icon: ReactNode }[] = row
    ? [
        { value: "start", label: "Top  ⌥W", icon: <AlignStartHorizontal /> },
        { value: "center", label: "Middle  ⌥V", icon: <AlignCenterHorizontal /> },
        { value: "end", label: "Bottom  ⌥S", icon: <AlignEndHorizontal /> },
      ]
    : [
        { value: "start", label: "Left  ⌥A", icon: <AlignStartVertical /> },
        { value: "center", label: "Center  ⌥H", icon: <AlignCenterVertical /> },
        { value: "end", label: "Right  ⌥D", icon: <AlignEndVertical /> },
      ]
  return <Segmented<Align | "auto"> value={value ?? "auto"} options={options} onChange={(v) => onChange(v === value ? undefined : (v as Align))} />
}

/** The four shells as tiny diagrams: easier to scan than words. */
function ShellPicker({ value, onChange }: { value: Shell; onChange: (s: Shell) => void }) {
  const opts: { value: Shell; label: string; draw: ReactNode }[] = [
    { value: "sidebar", label: "Sidebar", draw: <><rect x="1" y="1" width="10" height="26" rx="1.5" fill="currentColor" opacity=".35" /><rect x="14" y="4" width="21" height="3" rx="1" fill="currentColor" opacity=".5" /><rect x="14" y="10" width="21" height="14" rx="1.5" fill="currentColor" opacity=".18" /></> },
    { value: "topbar", label: "Top bar", draw: <><rect x="1" y="1" width="34" height="6" rx="1.5" fill="currentColor" opacity=".35" /><rect x="4" y="10" width="28" height="3" rx="1" fill="currentColor" opacity=".5" /><rect x="4" y="16" width="28" height="9" rx="1.5" fill="currentColor" opacity=".18" /></> },
