import { ACCENTS, BASES } from "./theme-data"

const same = (a: Theme = {}, b: Theme = {}) =>
  a.base === b.base && a.accent === b.accent && a.radius === b.radius && a.font === b.font && (a.mode ?? "light") === (b.mode ?? "light")

function Group({ title, value, children }: { title: string; value?: string; children: ReactNode }) {
  return (
    <section className="grid gap-2 px-4 py-3">
      <div className="flex items-baseline justify-between">
        <h3 className="text-[12px] font-medium">{title}</h3>
        {value && <span className="text-[11px] text-(--skc-muted) capitalize">{value}</span>}
      </div>
      {children}
    </section>
  )
}

function Swatch({ color, ring, active, title, onClick }: { color: string; ring?: string; active: boolean; title: string; onClick: () => void }) {
  return (
    <button
      type="button"
      title={title}
      aria-label={title}
      aria-pressed={active}
      onClick={onClick}
      className="relative size-6 rounded-full"
      style={{ background: color, boxShadow: active ? `0 0 0 2px var(--skc-bg), 0 0 0 4px ${ACCENT}` : `inset 0 0 0 1px ${ring ?? "rgba(0,0,0,.12)"}` }}
    >
      {active && <Check className="absolute inset-0 m-auto size-3 text-white mix-blend-difference" strokeWidth={3} />}
    </button>
  )
}

/** Fast theme picks: presets first, then each token on its own. Changes apply live to the sketch. */
export function ThemePanel({ theme, onChange, onClose }: { theme?: Theme; onChange: (t: Theme | undefined, merge?: string) => void; onClose: () => void }) {
  const t = theme ?? {}
  const ref = useRef<HTMLDivElement>(null)
  const set = (patch: Partial<Theme>, merge?: string) => {
    const next = { ...t, ...patch }
    for (const k of Object.keys(next) as (keyof Theme)[]) if (next[k] === undefined) delete next[k]
    onChange(Object.keys(next).length ? next : undefined, merge)
  }

  useEffect(() => FONTS.forEach((f) => loadFont(f.id)), [])
  useEffect(() => {
    const down = (e: PointerEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node) && !(e.target as HTMLElement).closest("[data-theme-trigger]")) onClose()
    }
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault()
        e.stopImmediatePropagation()
        onClose()
      }
    }
    window.addEventListener("pointerdown", down, true)
    window.addEventListener("keydown", key, true)
    return () => {
      window.removeEventListener("pointerdown", down, true)
      window.removeEventListener("keydown", key, true)
    }
  }, [onClose])

  return (
    <div
      ref={ref}
      className="skc-pop skc-scroll absolute top-[calc(100%+6px)] right-0 z-50 max-h-[calc(100vh-80px)] w-[340px] overflow-y-auto rounded-xl border border-(--skc-border) bg-(--skc-popover) shadow-[0_16px_48px_-12px_rgba(0,0,0,.28)]"
    >
      <div className="flex items-center justify-between border-b border-(--skc-border) px-4 py-2.5">
        <div className="min-w-0">
          <div className="font-medium">Theme</div>
          <div className="truncate text-[11px] text-(--skc-muted)">{describeTheme(theme)}</div>
        </div>
        {!isProjectTheme(theme) && (
          <button type="button" onClick={() => onChange(undefined)} className="h-7 rounded-md px-2 text-[12px] text-(--skc-muted) hover:bg-(--skc-hover) hover:text-(--skc-fg)">
            Reset
          </button>
        )}
      </div>

      <Group title="Presets">
        <div className="grid grid-cols-4 gap-2">
          {PRESETS.map((p) => {
            const v = themeVars(p.theme, p.theme.mode ?? "light")
            const active = same(t, p.theme)
            const font = fontOf(p.theme.font)
            const radius = p.theme.radius ?? 0.625
            return (
              <button
                key={p.id}
                type="button"
                aria-pressed={active}
                onClick={() => onChange(p.id === "project" ? undefined : { ...p.theme })}
                className="grid gap-1.5 rounded-lg p-1 text-left hover:bg-(--skc-hover)"
                style={{ boxShadow: active ? `0 0 0 2px ${ACCENT}` : undefined }}
              >
                <div
                  className="grid h-12 place-items-center overflow-hidden border"
                  style={{
                    borderRadius: Math.min(10, radius * 12 + 2),
                    background: v.background ?? "#fff",
                    color: v.foreground ?? "#111",
                    borderColor: v.border ?? "rgba(0,0,0,.1)",
                    fontFamily: font ? `"${font.family}"` : undefined,
                  }}
                >
                  <div className="flex items-center gap-1">
                    <span className="text-[15px] leading-none font-semibold">Aa</span>
                    <span className="size-2.5 rounded-full" style={{ background: v.primary ?? "#171717", borderRadius: radius ? 999 : 1 }} />
                  </div>
                </div>
                <span className="truncate px-0.5 text-[11px]">{p.name}</span>
              </button>
            )
          })}
        </div>
      </Group>

      <Group title="Base" value={t.base ?? "project"}>
        <div className="flex flex-wrap gap-2">
          {BASE_NAMES.map((b) => (
            <Swatch key={b} title={b} color={BASES[b].light["muted-foreground"]} active={t.base === b} onClick={() => set({ base: t.base === b ? undefined : b })} />
          ))}
        </div>
      </Group>

      <Group title="Accent" value={t.accent ?? "none"}>
        <div className="flex flex-wrap gap-2">
          {ACCENT_NAMES.map((a) => (
            <Swatch key={a} title={a} color={ACCENTS[a][500]} ring="transparent" active={t.accent === a} onClick={() => set({ accent: t.accent === a ? undefined : a })} />
          ))}
        </div>
      </Group>

      <Group title="Radius" value={t.radius !== undefined ? `${t.radius}rem` : "project"}>
        <div className="grid grid-cols-6 gap-1">
          {RADII.map((r) => (
            <button
              key={r}
              type="button"
              aria-pressed={t.radius === r}
              title={`${r}rem`}
              onClick={() => set({ radius: t.radius === r ? undefined : r })}
              className={`grid h-9 place-items-center rounded-md ${t.radius === r ? "bg-(--skc-active)" : "hover:bg-(--skc-hover)"}`}
            >
              <span className="block size-4 border-t-2 border-l-2 border-(--skc-fg)" style={{ borderTopLeftRadius: r * 14 }} />
            </button>
          ))}
        </div>
      </Group>

      <Group title="Font" value={fontOf(t.font)?.label ?? "project"}>
        <div className="grid grid-cols-2 gap-1">
          {FONTS.map((font) => (
            <button
              key={font.id}
              type="button"
              aria-pressed={t.font === font.id}
              onClick={() => set({ font: t.font === font.id ? undefined : font.id })}
              className={`flex h-9 items-center justify-between gap-2 rounded-md px-2.5 text-left ${t.font === font.id ? "bg-(--skc-active)" : "hover:bg-(--skc-hover)"}`}
            >
              <span className="truncate text-[13.5px]" style={{ fontFamily: `"${font.family}"` }}>
                {font.label}
              </span>
              {font.kind !== "sans" && <span className="text-[10px] text-(--skc-faint)">{font.kind}</span>}
            </button>
          ))}
        </div>
      </Group>

      <Group title="Preview">
        <Segmented<"light" | "dark">
          value={t.mode ?? "light"}
          onChange={(mode) => set({ mode: mode === "light" ? undefined : mode })}
          options={[
            { value: "light", label: "Light", icon: <span className="flex items-center gap-1.5 [&_svg]:size-3.5"><Sun /> Light</span> },
            { value: "dark", label: "Dark", icon: <span className="flex items-center gap-1.5 [&_svg]:size-3.5"><Moon /> Dark</span> },
          ]}
        />
      </Group>
      <p className="px-4 pb-4 text-[11px] leading-relaxed text-(--skc-faint)">The prompt carries the tokens and font install, so your agent applies the same theme to the project.</p>
    </div>
  )
}

// Themes: pick a base palette, an accent, a radius and a font, like `shadcn create`.
// Nothing set means the project's own theme; every choice is an override on top of it.

import type { CSSProperties } from "react"
import { ACCENTS, BASES } from "./theme-data"
import type { Vars } from "./theme-data"

export type Theme = {
  base?: string
  accent?: string
  /** rem */
  radius?: number
  font?: string
  /** How the sketch is previewed. */
  mode?: "light" | "dark"
}

export const BASE_NAMES = Object.keys(BASES)
export const ACCENT_NAMES = Object.keys(ACCENTS)
export const RADII = [0, 0.3, 0.5, 0.625, 0.75, 1]

export type Font = { id: string; label: string; family: string; google: string; fontsource: string; kind: "sans" | "serif" | "mono" }
const f = (id: string, label: string, google: string, fontsource: string, kind: Font["kind"] = "sans"): Font => ({ id, label, family: label, google, fontsource, kind })
export const FONTS: Font[] = [
  f("geist", "Geist", "Geist:wght@100..900", "@fontsource-variable/geist"),
  f("inter", "Inter", "Inter:wght@100..900", "@fontsource-variable/inter"),
  f("figtree", "Figtree", "Figtree:wght@300..900", "@fontsource-variable/figtree"),
  f("dm-sans", "DM Sans", "DM+Sans:wght@100..1000", "@fontsource-variable/dm-sans"),
  f("manrope", "Manrope", "Manrope:wght@200..800", "@fontsource-variable/manrope"),
  f("plus-jakarta", "Plus Jakarta Sans", "Plus+Jakarta+Sans:wght@200..800", "@fontsource-variable/plus-jakarta-sans"),
  f("outfit", "Outfit", "Outfit:wght@100..900", "@fontsource-variable/outfit"),
  f("nunito-sans", "Nunito Sans", "Nunito+Sans:wght@200..1000", "@fontsource-variable/nunito-sans"),
  f("space-grotesk", "Space Grotesk", "Space+Grotesk:wght@300..700", "@fontsource-variable/space-grotesk"),
  f("ibm-plex", "IBM Plex Sans", "IBM+Plex+Sans:wght@100..700", "@fontsource-variable/ibm-plex-sans"),
  f("source-serif", "Source Serif 4", "Source+Serif+4:wght@200..900", "@fontsource-variable/source-serif-4", "serif"),
  f("geist-mono", "Geist Mono", "Geist+Mono:wght@100..900", "@fontsource-variable/geist-mono", "mono"),
  f("jetbrains-mono", "JetBrains Mono", "JetBrains+Mono:wght@100..800", "@fontsource-variable/jetbrains-mono", "mono"),
]
export const fontOf = (id?: string) => FONTS.find((x) => x.id === id)

export type Preset = { id: string; name: string; theme: Theme }
export const PRESETS: Preset[] = [
  { id: "project", name: "Project", theme: {} },
  { id: "ocean", name: "Ocean", theme: { base: "slate", accent: "blue", radius: 0.5, font: "inter" } },
  { id: "forest", name: "Forest", theme: { base: "stone", accent: "emerald", radius: 0.75, font: "figtree" } },
  { id: "sunset", name: "Sunset", theme: { base: "taupe", accent: "orange", radius: 1, font: "outfit" } },
  { id: "grape", name: "Grape", theme: { base: "mauve", accent: "violet", radius: 0.625, font: "plus-jakarta" } },
  { id: "rose", name: "Rose", theme: { base: "neutral", accent: "rose", radius: 0.75, font: "dm-sans" } },
  { id: "editorial", name: "Editorial", theme: { base: "olive", radius: 0.3, font: "source-serif" } },
  { id: "terminal", name: "Terminal", theme: { base: "zinc", accent: "lime", radius: 0, font: "jetbrains-mono", mode: "dark" } },
]

const LIGHT_ACCENTS = new Set(["amber", "yellow", "lime"])

/** Accent tokens for one mode. */
function accentVars(name: string, mode: "light" | "dark"): Vars {
  const a = ACCENTS[name]
  if (!a) return {}
  const pale = LIGHT_ACCENTS.has(name)
  const primary = mode === "dark" || pale ? a[500] : a[600]
  const fg = pale ? a[950] : "oklch(0.985 0 0)"
  return {
    primary,
    "primary-foreground": fg,
    ring: a[400],
    "chart-1": a[300],
    "chart-2": a[500],
    "chart-3": a[600],
    "chart-4": a[700],
    "chart-5": a[800],
    "sidebar-primary": primary,
    "sidebar-primary-foreground": fg,
    "sidebar-ring": a[400],
  }
}

/** Every token the theme changes, for one mode. */
export function themeVars(t: Theme | undefined, mode: "light" | "dark"): Vars {
  if (!t) return {}
  const v: Vars = { ...(t.base ? BASES[t.base]?.[mode] : {}), ...(t.accent ? accentVars(t.accent, mode) : {}) }
  if (t.radius !== undefined) v.radius = `${t.radius}rem`
  const font = fontOf(t.font)
  if (font) v["font-sans"] = `"${font.family}", ui-sans-serif, system-ui, sans-serif`
  return v
}

/** Inline style that applies the theme to an element (the frame or a thumbnail). */
export function themeStyle(t: Theme | undefined): CSSProperties {
  const vars = themeVars(t, t?.mode ?? "light")
  const style: Record<string, string> = {}
  for (const [k, val] of Object.entries(vars)) style[`--${k}`] = val
  if (vars["font-sans"]) style.fontFamily = vars["font-sans"]
  return style as CSSProperties
}

export const isProjectTheme = (t?: Theme) => !t || (!t.base && !t.accent && t.radius === undefined && !t.font)

/** Loads a Google font for the preview, once. The project itself should install the fontsource package. */
export function loadFont(id?: string) {
  const font = fontOf(id)
  if (!font || typeof document === "undefined") return
  if (document.querySelector(`link[data-sketchcn-font="${font.id}"]`)) return
  const link = document.createElement("link")
  link.rel = "stylesheet"
  link.href = `https://fonts.googleapis.com/css2?family=${font.google}&display=swap`
  link.dataset.sketchcnFont = font.id
  document.head.appendChild(link)
}

/** The theme as CSS the agent can paste into the project's globals.css. */
export function themeCSS(t: Theme | undefined) {
  if (isProjectTheme(t)) return ""
  const block = (sel: string, vars: Vars) => {
    const lines = Object.entries(vars)
      .filter(([k]) => k !== "font-sans")
      .map(([k, v]) => `  --${k}: ${v};`)
    return lines.length ? `${sel} {\n${lines.join("\n")}\n}` : ""
  }
  const light = themeVars(t, "light")
  const dark = themeVars(t, "dark")
  delete dark.radius
  const font = fontOf(t?.font)
  const theme = font ? `@theme inline {\n  --font-sans: "${font.family}${font.fontsource.includes("variable") ? " Variable" : ""}", ui-sans-serif, system-ui, sans-serif;\n}` : ""
  return [block(":root", light), block(".dark", dark), theme].filter(Boolean).join("\n\n")
}

export function describeTheme(t: Theme | undefined) {
  if (isProjectTheme(t)) return "Project theme"
  return [t?.base && `${t.base} base`, t?.accent && `${t.accent} accent`, t?.radius !== undefined && `${t.radius}rem radius`, fontOf(t?.font)?.label]
    .filter(Boolean)
    .join(" · ")
}
